style.css:
/* Tori Vintage Red — Roblox */
/* i really want this to be global */

:root {
  --tori-bg: url("https://i.pinimg.com/736x/69/3d/11/693d1100e3f4b244b812bdb21814c57f.jpg");
}

/* Fundo normal */
html,
body {
  background: #35070d !important;
}

/* TESTE: coloca a imagem diretamente na tela */
body::after {
  content: "" !important;

  position: fixed !important;
  left: 0 !important;
  top: 0 !important;
  width: 100vw !important;
  height: 100vh !important;

  background-image: var(--tori-bg) !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-size: cover !important;

  z-index: 999999 !important;

  pointer-events: none !important;

  opacity: 1 !important;
}
